/* ---------------------------------------------------------------
   sortie-audio.js — envoyer le son vers la voiture.

   Le problème, et il ne vient pas de cette application : sur iPhone,
   la voix de synthèse d'une page web est traitée comme un son
   système, au même titre qu'une notification. Les sons système
   sortent sur le haut-parleur du téléphone et ne suivent ni le
   Bluetooth ni CarPlay. C'est vrai dans Safari avec n'importe quel
   site, pas seulement ici.

   Le contournement tenté : maintenir une lecture média en cours —
   un silence numérique en boucle — pour que l'appareil range
   l'application du côté des lecteurs de musique plutôt que des sons
   système, et fasse suivre la sortie choisie.

   Ça ne peut pas être garanti : le comportement dépend de la version
   d'iOS et de l'autoradio. D'où un réglage à activer soi-même, et
   désactivé par défaut — car une lecture média en cours interrompt
   la radio ou la musique de la voiture, ce qu'on ne veut pas imposer
   à quelqu'un qui joue simplement sur son canapé.
   --------------------------------------------------------------- */

window.Jeu = window.Jeu || {};

Jeu.SortieAudio = (function () {
  var SILENCE = 'data:audio/wav;base64,';

  var element = null;
  var active = false;

  function creer() {
    if (element) return element;
    element = document.createElement('audio');
    element.src = SILENCE;
    element.loop = true;
    element.preload = 'auto';
    element.setAttribute('playsinline', '');
    element.volume = 1;              // le fichier est silencieux par construction
    element.style.display = 'none';
    document.body.appendChild(element);
    return element;
  }

  /* À appeler depuis un geste de l'utilisateur : les navigateurs
     refusent de démarrer une lecture autrement. */
  function ouvrir() {
    if (!Jeu.Reglages.get('sonVoiture')) return Promise.resolve(false);
    var a = creer();
    var p = a.play();
    if (!p || !p.then) { active = true; return Promise.resolve(true); }
    return p.then(function () {
      active = true;
      return true;
    }).catch(function () {
      active = false;
      return false;
    });
  }

  function fermer() {
    if (!element) return;
    try { element.pause(); } catch (e) { /* rien */ }
    active = false;
  }

  function ouverte() { return active; }

  /* La session se rouvre au premier geste, et se referme quand le
     réglage est coupé. */
  function installer() {
    function auPremierGeste() {
      ouvrir();
      document.removeEventListener('pointerdown', auPremierGeste);
      document.removeEventListener('keydown', auPremierGeste);
    }
    document.addEventListener('pointerdown', auPremierGeste);
    document.addEventListener('keydown', auPremierGeste);

    Jeu.Reglages.surChangement(function (cle) {
      if (cle !== 'sonVoiture' && cle !== '*') return;
      if (Jeu.Reglages.get('sonVoiture')) ouvrir();
      else fermer();
    });

    // L'application revient au premier plan : la session a pu être
    // coupée par le système entre-temps.
    document.addEventListener('visibilitychange', function () {
      if (!document.hidden && Jeu.Reglages.get('sonVoiture')) ouvrir();
    });
  }

  return { installer: installer, ouvrir: ouvrir, fermer: fermer, ouverte: ouverte };
})();
